def solve_n_queens(n, fixed):
    def can_place(pos, ocuppied_positions):
        for i in range(len(ocuppied_positions)):
            if ocuppied_positions[i] == pos or \
                ocuppied_positions[i] - i == pos - len(ocuppied_positions) or \
                ocuppied_positions[i] + i == pos + len(ocuppied_positions):
                return False
        return True

    def solve(row, current_solution):
        if row == n:
            return current_solution

        if row in fixed:
            if can_place(fixed[row], current_solution):
                return solve(row + 1, current_solution + [fixed[row]])
            else:
                return None

        for col in range(n):
            if can_place(col, current_solution):
                result = solve(row + 1, current_solution + [col])
                if result:
                    return result
        return None

