def solve_n_queens(n, fixed):
    solutions = []
    def solve(row, current_solution):
        if row == n:
            solutions.append(current_solution)
            return

        if row in fixed:
            col = fixed[row]
            valid = True
            for i in range(row):
                if current_solution[i] == col or \
                   abs(current_solution[i] - col) == abs(i - row):
                    valid = False
                    break
            if valid:
                solve(row + 1, current_solution + [col])
            return

        for col in range(n):
            valid = True
            for i in range(row):
                if current_solution[i] == col or \
                   abs(current_solution[i] - col) == abs(i - row):
                    valid = False
                    break
            if valid:
                solve(row + 1, current_solution + [col])

    solve(0, [])
    return solutions

